// Build the ComfyUI API workflow (SDXL text-to-image).
// Either uses the user-supplied prompt, or synthesises one from the listing.
const body = $('Webhook').first().json.body || $('Webhook').first().json;
const listing = $('Fetch Listing').first().json;

if (!listing) throw new Error(`Listing ${body.listing_id} not found`);

const userPrompt = (body.prompt || '').trim();
const prompt = userPrompt || `${listing.title}. ${listing.niche || ''}. clean studio mockup, soft lighting, high detail, product photography style`;

const negative = body.negative || 'low quality, blurry, watermark, text, signature, deformed';
const width  = Math.min(Math.max(parseInt(body.width  || 1024, 10), 256), 2048);
const height = Math.min(Math.max(parseInt(body.height || 1024, 10), 256), 2048);
const steps  = Math.min(Math.max(parseInt(body.steps  || 25,  10), 1),   80);
const cfg    = Math.min(Math.max(parseFloat(body.cfg  ?? 7.0),     1.0), 15.0);
const seed   = body.seed != null ? parseInt(body.seed, 10) : Math.floor(Math.random() * 1e9);
const checkpoint = body.checkpoint || 'sd_xl_base_1.0.safetensors';
const clientId   = `n8n-${$execution.id}`;
const filenamePrefix = `etsy/listing-${listing.listing_id}`;

// ComfyUI API workflow (node graph). Loads checkpoint, encodes prompts,
// runs the sampler, decodes latent, saves PNG to ComfyUI's output dir.
const workflow = {
  '4': { class_type: 'CheckpointLoaderSimple', inputs: { ckpt_name: checkpoint } },
  '5': { class_type: 'EmptyLatentImage',       inputs: { width, height, batch_size: 1 } },
  '6': { class_type: 'CLIPTextEncode',         inputs: { text: prompt,   clip: ['4', 1] } },
  '7': { class_type: 'CLIPTextEncode',         inputs: { text: negative, clip: ['4', 1] } },
  '3': { class_type: 'KSampler', inputs: {
            seed, steps, cfg,
            sampler_name: 'euler', scheduler: 'normal', denoise: 1,
            model:        ['4', 0],
            positive:     ['6', 0],
            negative:     ['7', 0],
            latent_image: ['5', 0] } },
  '8': { class_type: 'VAEDecode',  inputs: { samples: ['3', 0], vae: ['4', 2] } },
  '9': { class_type: 'SaveImage',  inputs: { filename_prefix: filenamePrefix, images: ['8', 0] } }
};

return [{ json: { listing_id: listing.listing_id, prompt, negative, width, height, seed, steps, cfg, checkpoint, client_id: clientId, comfy_payload: { prompt: workflow, client_id: clientId } } }];

// Poll ComfyUI /history/<prompt_id> until the job completes,
// then return the first SaveImage output (filename + subfolder).
const queued = $input.first().json;
const promptId = queued.prompt_id || queued.body?.prompt_id;
if (!promptId) throw new Error(`No prompt_id from ComfyUI: ${JSON.stringify(queued)}`);

const TIMEOUT_MS = 5 * 60 * 1000;
const POLL_MS = 2000;
const start = Date.now();

while (Date.now() - start < TIMEOUT_MS) {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: `http://comfyui:8188/history/${promptId}`,
    json: true
  });
  const entry = res[promptId];
  if (entry && entry.outputs && Object.keys(entry.outputs).length > 0) {
    for (const nodeId of Object.keys(entry.outputs)) {
      const out = entry.outputs[nodeId];
      if (out.images?.length) {
        const img = out.images[0];
        return [{ json: { prompt_id: promptId, filename: img.filename, subfolder: img.subfolder || '', type: img.type || 'output' } }];
      }
    }
    throw new Error(`Job ${promptId} completed but produced no images`);
  }
  await new Promise(r => setTimeout(r, POLL_MS));
}
throw new Error(`ComfyUI job ${promptId} timed out after ${TIMEOUT_MS}ms`);
